CREATE TABLE IF NOT EXISTS manager_schema_migrations(version integer PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE sites(id text PRIMARY KEY, name text NOT NULL, origins jsonb NOT NULL, widget_origins jsonb NOT NULL, config jsonb NOT NULL, enabled boolean NOT NULL DEFAULT true);
CREATE TABLE customers(id uuid PRIMARY KEY, name text NOT NULL, contacts jsonb NOT NULL, erp_contact_id text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE customer_identities(id uuid PRIMARY KEY, customer_id uuid NOT NULL REFERENCES customers(id), site_id text NOT NULL REFERENCES sites(id), kind text NOT NULL CHECK(kind IN ('session','email','phone')), value text NOT NULL, verified boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX customer_verified_identity ON customer_identities(site_id, kind, value) WHERE verified;
CREATE INDEX customer_identity_candidates ON customer_identities(kind,value);
CREATE TABLE guest_sessions(id uuid PRIMARY KEY, token_hash text NOT NULL UNIQUE, site_id text NOT NULL REFERENCES sites(id), origin text NOT NULL, source jsonb NOT NULL, expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE inquiries(id uuid PRIMARY KEY, session_id uuid NOT NULL UNIQUE REFERENCES guest_sessions(id), site_id text NOT NULL REFERENCES sites(id), customer_id uuid NOT NULL REFERENCES customers(id), topic_id uuid UNIQUE, source jsonb NOT NULL, assignee_id uuid, manually_assigned boolean NOT NULL DEFAULT false, chat_cursor bigint NOT NULL DEFAULT 0, status text NOT NULL DEFAULT 'OPEN' CHECK(status IN ('OPEN','CLOSED')), created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX inquiries_customer_history ON inquiries(customer_id,created_at);
CREATE TABLE attachments(id uuid PRIMARY KEY, session_id uuid NOT NULL REFERENCES guest_sessions(id), operation_id text NOT NULL, fingerprint text NOT NULL, name text NOT NULL, size bigint NOT NULL, mime text NOT NULL, chat_id uuid, inquiry_id uuid REFERENCES inquiries(id), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(session_id,operation_id));
CREATE TABLE messages(id uuid PRIMARY KEY, inquiry_id uuid NOT NULL REFERENCES inquiries(id), sequence bigserial NOT NULL UNIQUE, operation_id text, fingerprint text, direction text NOT NULL CHECK(direction IN ('incoming','outgoing')), author text NOT NULL, actor_id uuid, avatar_url text, html text NOT NULL, attachments jsonb NOT NULL DEFAULT '[]', chat_message_id uuid UNIQUE, created_at timestamptz NOT NULL DEFAULT now(), read_at timestamptz, UNIQUE(inquiry_id,operation_id));
CREATE INDEX messages_inquiry_sequence ON messages(inquiry_id,sequence);
CREATE TABLE delivery_operations(id uuid PRIMARY KEY REFERENCES messages(id), inquiry_id uuid NOT NULL REFERENCES inquiries(id), state text NOT NULL DEFAULT 'pending' CHECK(state IN ('pending','working','delivered','failed')), attempts integer NOT NULL DEFAULT 0, next_attempt_at timestamptz NOT NULL DEFAULT now(), locked_until timestamptz, last_error text, updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX delivery_pending ON delivery_operations(next_attempt_at) WHERE state IN ('pending','working');
CREATE TABLE assignment_events(id uuid PRIMARY KEY, inquiry_id uuid NOT NULL REFERENCES inquiries(id), previous_user_id uuid, user_id uuid NOT NULL, actor_id uuid, reason text NOT NULL CHECK(reason IN ('first_reply','manual')), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE erp_sync_operations(id uuid PRIMARY KEY, customer_id uuid NOT NULL REFERENCES customers(id), actor_id uuid NOT NULL, state text NOT NULL DEFAULT 'pending', erp_contact_id text, last_error text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX erp_sync_active_customer ON erp_sync_operations(customer_id) WHERE state IN ('pending','working','completed');
CREATE TABLE widget_events(sequence bigserial PRIMARY KEY, session_id uuid NOT NULL REFERENCES guest_sessions(id), message_id uuid NOT NULL REFERENCES messages(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX widget_events_session ON widget_events(session_id,sequence);
CREATE TABLE rate_buckets(key text PRIMARY KEY, window_start timestamptz NOT NULL, count integer NOT NULL);
